#include <iostream>
#include <vector>
using namespace std;

struct Node {
    int data;
    Node *left, *right;
    Node(int v) : data(v), left(nullptr), right(nullptr) {}
};

int main() {
    Node* root = new Node(4);
    root->left = new Node(2);
    root->right = new Node(6);
    cout << root->data << '\n';
    return 0;
}

